                Gizmos.color = new Color(0f, 0f, 0f, 0f);
                for (int boneIndex = 0; boneIndex < boneCount; boneIndex++)
                {
                    bonesToDraw[boneIndex].DrawSpringBoneCollision();
                }
            }

            for (int boneIndex = 0; boneIndex < boneCount; boneIndex++)
